function prepare({ payload, dataSourceId, personId }) {
  if (
    typeof dataSourceId !== "string" ||
    !dataSourceId.trim() ||
    dataSourceId.startsWith("YOUR_") ||
    typeof personId !== "string" ||
    !personId.trim() ||
    personId.startsWith("YOUR_")
  )
    throw Error("Configure the Notion data source and person");
  if (
    !payload ||
    typeof payload.email !== "string" ||
    !payload.email.trim() ||
    typeof payload.name !== "string" ||
    !payload.name.trim()
  )
    throw Error("Booking is missing the invitee name or email");
  const e = payload.scheduled_event,
    start = e?.start_time,
    end = e?.end_time;
  if (
    typeof start !== "string" ||
    typeof end !== "string" ||
    !Number.isFinite(Date.parse(start)) ||
    !Number.isFinite(Date.parse(end)) ||
    Date.parse(end) <= Date.parse(start)
  )
    throw Error("Booking has invalid scheduled event times");
  const contact = { email: payload.email, full_name: payload.name };
  for (const k of ["first_name", "last_name"])
    if (typeof payload[k] === "string" && payload[k].trim()) contact[k] = payload[k];
  return { data: [contact], booking: { start, end }, dataSourceId, personId };
}

return $input.all().flatMap((x, i) => {
  if (x.json.event !== "invitee.created") return [];
  const p = prepare({
    payload: x.json.payload,
    dataSourceId: "YOUR_NOTION_DATA_SOURCE_ID",
    personId: "YOUR_NOTION_PERSON_ID",
  });
  return [
    {
      json: {
        ...p.data[0],
        booking: p.booking,
        dataSourceId: p.dataSourceId,
        personId: p.personId,
      },
      pairedItem: { item: i },
    },
  ];
});

function page({ data, error, success, status, booking, dataSourceId, personId }) {
  if (
    error !== false ||
    success !== true ||
    status !== "succeeded" ||
    !Array.isArray(data) ||
    data.length !== 1
  )
    throw Error("Dropcontact enrichment is not complete; inspect the request before retrying");
  if (
    typeof dataSourceId !== "string" ||
    !dataSourceId.trim() ||
    dataSourceId.startsWith("YOUR_") ||
    typeof personId !== "string" ||
    !personId.trim() ||
    personId.startsWith("YOUR_")
  )
    throw Error("Configure the Notion data source and person");
  const r = data[0],
    email = r?.email?.[0]?.email;
  if (
    typeof r?.full_name !== "string" ||
    !r.full_name.trim() ||
    typeof email !== "string" ||
    !email.trim()
  )
    throw Error("Enriched contact is missing full name or first email");
  const properties = {
    Date: { date: { start: booking.start, end: booking.end } },
    email: { email },
    Leads: { title: [{ text: { content: r.full_name } }] },
    Person: { people: [{ id: personId }] },
  };
  for (const [source, target] of [
    ["linkedin", "LinkedIn Profile"],
    ["website", "Website"],
    ["company_linkedin", "LinkedIn Company"],
  ]) {
    const v = r[source];
    if (v === undefined || v === null || v === "") continue;
    if (typeof v !== "string") throw Error("Invalid enriched URL");
    properties[target] = { url: v };
  }
  if (r.civility !== undefined && r.civility !== null && r.civility !== "") {
    if (typeof r.civility !== "string") throw Error("Invalid civility");
    properties.Civility = { rich_text: [{ text: { content: r.civility } }] };
  }
  return { parent: { data_source_id: dataSourceId }, properties };
}

const p = $("Prepare booking and contact").first().json;
return [
  {
    json: page({
      data: $input.all().map((x) => x.json),
      error: false,
      success: true,
      status: "succeeded",
      booking: p.booking,
      dataSourceId: p.dataSourceId,
      personId: p.personId,
    }),
  },
];

function notionBookingCreated({ page }) {
  if (
    !page ||
    typeof page !== "object" ||
    Array.isArray(page) ||
    page.object !== "page" ||
    typeof page.id !== "string" ||
    !page.id.trim()
  ) {
    throw new Error("Notion did not return a created page ID");
  }
  return { page };
}

return $input.all().map((x) => ({ json: notionBookingCreated({ page: x.json }).page }));
